// *** 1. 解析輸入資料 ***
// 假設 Aggregate 節點的輸出結構是：
// items[0].json.data (包含所有經 Merge 節點合併後的食譜陣列)

// 修正：mergedRecipeData 包含 AI 摘要結果 (在 .output 內) 和原始食譜資料 (例如：original_url)
const mergedRecipeData = items[0].json.data;

// *** 刪除手動定義的 mockMetadata (已不再需要) ***
// const mockMetadata = [ ... ]; // 請確保您已經刪除原程式碼中的 mockMetadata 定義

const carouselColumns = [];
const maxRecipes = Math.min(mergedRecipeData.length, 10);

// *** 2. 數據迭代與模板填充 ***
for (let i = 0; i < maxRecipes; i++) {
  // 從合併後的數據中直接提取所有必要的欄位
  const recipe = mergedRecipeData[i];

  // 由於 Merge 節點是以 Replace 模式合併，AI 摘要結果通常會保留在 .output 欄位中
  const aiOutput = recipe.output; 

  // 原始連結和圖片直接從 recipe 物件中獲取
  const original_url = recipe.original_url || ''; 
  const original_title = recipe.original_title || (aiOutput ? aiOutput.ai_title : '未知食譜'); 

  // **【關鍵修正】：檢查圖片 URL 是否為 Base64，如果是則替換為有效 HTTPS 網址**
  let image_url = recipe.image_url;
  const default_image = 'https://fakeimg.pl/400x400/CCCCCC/000000?text=No+Image';

  if (!image_url || image_url.startsWith('data:')) {
    // 如果圖片不存在，或是 Base64 (以 "data:" 開頭)，則使用預設圖片
    image_url = default_image;
  }
  // 否則，保持原本的 image_url (必須假設它是有效的 HTTPS 網址)

  // 確保 AI 摘要欄位存在
  const ai_title = aiOutput ? aiOutput.ai_title : '食譜標題缺失';
  const ai_summary = aiOutput ? aiOutput.ai_summary : '食譜摘要缺失';

  const column = {
    "thumbnailImageUrl": image_url, 
    // LINE Carousel 模板允許 Image Background Color
    "imageBackgroundColor": "#FFFFFF", 
    "title": ai_title, 
    "text": ai_summary,

    // 設定預設動作，點擊圖片區域時觸發
    "defaultAction": {
      "type": "uri",
      "label": "查看詳情",
      "uri": original_url // <--- 使用真實連結
    },

    // 設定底部的動作按鈕
    "actions": [
      {
        "type": "uri",
        "label": "查看完整食譜 (原網址)",
        "uri": original_url // <--- 使用真實連結
      },
      // Message Action：觸發後續的 Bot 流程 (詢問材料清單)
      {
       "type": "postback",
        "label": "查詢完整材料清單", // 簡潔的按鈕文字

        // *** 這是核心修改點：將 URL 嵌入 data 欄位 ***
        // 格式：action=指令&recipe_url=完整URL
        "data": `action=get_ingredients&recipe_url=${encodeURIComponent(recipe.original_url)}`,

        // (選用) 點擊後在聊天室顯示的文字，讓使用者知道發生了什麼事
        "displayText": `正在查詢 ${aiOutput.ai_title} 的材料清單...` // <--- 使用真實標題
      }
    ]
  };

  carouselColumns.push(column);
}

// ... (程式碼後半段不變)

// 移除原有的 lineResponse 結構，直接輸出 messages 陣列
const lineMessages = [
  {
    "type": "template",
    "altText": `AI為您精選了 ${maxRecipes} 個食譜！請點擊查看詳情。`, 
    "template": {
      "type": "carousel",
      "columns": carouselColumns
    }
  }
];
// ... (您的 lineMessages 陣列定義，包含所有 LINE 訊息)

// 創建一個包含 'messages' 屬性的物件
const outputObject = {
    messages: lineMessages
};

// 讓 Code 節點返回這個物件
return [{ json: outputObject }];

parameters.text:
=你是一位專業食譜編輯。任務是根據以下原始食譜資料，產生一個符合 LINE Carousel 格式要求的簡短摘要。

原始食譜標題：{{$json.title}}
原始食譜材料：{{$json.ingredients_raw}}
原始食譜步驟：{{$json.steps_raw}}

請嚴格依照以下 JSON 格式輸出，並遵守字數限制：
1. "ai_title": 必須是吸引人的短標題，不超過 40 個字符。
2. "ai_summary": 請簡述主要食材、關鍵步驟，並提供「一個烹飪秘訣」，總共不超過 60 個字符。

{
  "ai_title": "精選標題", 
  "ai_summary": "精選摘要"
}
